# our updated program here
import time
import numpy as np
import random
import math
from copy import deepcopy

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)  # including depot node 0

    # --- implementation of Fragmented Memetic Reconstructor style solver ---
    def solve(self,
              time_limit: float = 5.0,
              seed: int = 0,
              params: dict = None) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP) using a fragmented memetic approach.

        Args:
            time_limit: time limit in seconds for the solver.
            seed: RNG seed.
            params: optional dictionary to tune behavior.

        Returns:
            Flat list route encoding with 0 as depot separators.
        """
        rnd = random.Random(seed)
        np.random.seed(seed)

        # default parameters
        if params is None:
            params = {}
        pop_size = params.get("pop_size", 30)
        init_frag_sizes = params.get("init_frag_sizes", [2, 3, 4])
        parent_strategy = params.get("parent_strategy", "tournament")  # or 'random'
        sample_budget = params.get("sample_budget", 10)
        assembler = params.get("assembler", "greedy")
        local_ops = params.get("local_ops", {"2opt_iters": 50, "relocate_iters": 50})
        replacement_strategy = params.get("replacement_strategy", "replace_worst")
        hotspot_criteria = params.get("hotspot_criteria", {"top_k": 3})
        intensify_budget = params.get("intensify_budget", 10)
        stagnation_limit = params.get("stagnation_limit", 50)
        frag_sizes = list(init_frag_sizes)
        max_routes = params.get("max_routes", self.n)  # upper bound

        # Utilities
        def evaluate(individual_routes):
            # individual_routes: list of routes (each route is list of customer indices excluding depot)
            total = 0.0
            for r in individual_routes:
                if len(r) == 0:
                    continue
                prev = 0
                for cust in r:
                    total += self.distance_matrix[prev, cust]
                    prev = cust
                total += self.distance_matrix[prev, 0]
            return total

        def route_demand(route):
            return sum(self.demands[i] for i in route)

        # Initialize population: randomized greedy pack
        def initialize_population(seed_pop):
            pop = []
            customers = list(range(1, self.n))
            for i in range(seed_pop):
                order = customers[:]
                rnd.shuffle(order)
                routes = []
                cur = []
                cur_load = 0
                for c in order:
                    d = self.demands[c]
                    if cur_load + d > self.vehicle_capacity:
                        if cur:
                            routes.append(cur)
                        cur = [c]
                        cur_load = d
                    else:
                        cur.append(c)
                        cur_load += d
                if cur:
                    routes.append(cur)
                pop.append(routes)
            return pop

        # Fragment pool: fragments are tuples of customers (subsequences)
        class FragmentPool:
            def __init__(self):
                self.pool = []  # list of dicts: {'seq': tuple, 'score': float, 'count': int, 'age': int}
                self.index = {}  # map seq -> idx

            def add(self, seq, score=1.0):
                key = tuple(seq)
                if key in self.index:
                    idx = self.index[key]
                    entry = self.pool[idx]
                    entry['count'] += 1
                    entry['score'] = (entry['score'] * (entry['count'] - 1) + score) / entry['count']
                    entry['age'] = 0
                else:
                    entry = {'seq': key, 'score': score, 'count': 1, 'age': 0}
                    self.index[key] = len(self.pool)
                    self.pool.append(entry)

            def sample(self, k, compat_model):
                if len(self.pool) == 0:
                    return []
                # weight by score and by compatibility (avg pairwise compat within seq)
                weights = []
                for e in self.pool:
                    base = max(1e-6, e['score'])
                    # compatibility: sum of compat for pairs in seq
                    seq = e['seq']
                    compat = 0.0
                    if len(seq) >= 2:
                        for a in seq:
                            for b in seq:
                                if a != b:
                                    compat += compat_model.get(a, {}).get(b, 0.0)
                        compat /= (len(seq) * max(1, (len(seq)-1)))
                    weights.append(base * (1.0 + compat))
                # normalize
                s = sum(weights)
                if s <= 0:
                    probs = [1.0 / len(weights)] * len(weights)
                else:
                    probs = [w / s for w in weights]
                chosen = rnd.choices(self.pool, weights=probs, k=min(k, len(self.pool)))
                return [list(e['seq']) for e in chosen]

            def decay(self):
                # age fragments, degrade score slightly for old entries
                new_pool = []
                new_index = {}
                for i, e in enumerate(self.pool):
                    e['age'] += 1
                    # optional aging removal
                    if e['age'] < 200:
                        # slight decay
                        e['score'] *= 0.999
                        new_index[e['seq']] = len(new_pool)
                        new_pool.append(e)
                self.pool = new_pool
                self.index = new_index

            def diversify(self, all_customers, sizes, rnd_local):
                # add some random fragments
                for s in sizes:
                    if s <= 0:
                        continue
                    seq = rnd_local.sample(all_customers, min(s, len(all_customers)))
                    self.add(seq, score=1.0)

            def update_with_candidate(self, fragments_used, candidate_score):
                for f in fragments_used:
                    self.add(f, score=candidate_score)

        # Compatibility model: nested dict default 0
        class CompatModel:
            def __init__(self, n):
                self.n = n
                self.co = {}  # co-occurrence weights dict of dict
                self.count = 0

            def online_update(self, fragments, score):
                # promote positive fragments: fragments are lists of nodes
                factor = 1.0 / (1.0 + score)
                for frag in fragments:
                    for i in frag:
                        for j in frag:
                            if i == j:
                                continue
                            self.co.setdefault(i, {})
                            self.co[i][j] = self.co[i].get(j, 0.0) + factor
                self.count += 1

            def get(self, a, b):
                return self.co.get(a, {}).get(b, 0.0)

        # Sample fragments from parents by extracting subsequences
        def sample_fragments_from_parents(parents, pool, compat, budget):
            fragments = []
            # prefer fragments from pool sampled plus some direct fragments from parents
            fragments.extend(pool.sample(max(1, budget//2), compat))
            # extract contiguous fragments from parent routes
            for p in parents:
                for r in p:
                    L = len(r)
                    if L == 0:
                        continue
                    # sample random subsequences
                    for _ in range(max(1, budget // max(1, len(parents)))):
                        a = rnd.randrange(0, L)
                        b = rnd.randrange(a, L)
                        frag = r[a:b+1]
                        if frag:
                            fragments.append(frag)
                            if len(fragments) >= budget:
                                return fragments
            return fragments[:budget]

        # Constraint-aware reconstruct: assemble fragments greedily into routes while respecting capacity
        def constraint_aware_reconstruct(fragments, all_customers, assembler_mode='greedy'):
            assigned = set()
            routes = []
            # First place fragments that fit
            # sort fragments by length desc (bigger pieces first)
            frags = sorted(fragments, key=lambda x: -len(x))
            for frag in frags:
                if any(c in assigned for c in frag):
                    continue
                load = sum(self.demands[c] for c in frag)
                placed = False
                # try to put into existing route if capacity allows
                for r in routes:
                    if route_demand(r) + load <= self.vehicle_capacity:
                        r.extend(frag)
                        for c in frag:
                            assigned.add(c)
                        placed = True
                        break
                if not placed:
                    # start new route
                    if load <= self.vehicle_capacity:
                        routes.append(list(frag))
                        for c in frag:
                            assigned.add(c)
            # fill remaining customers greedily by nearest insertion
            remaining = [c for c in all_customers if c not in assigned]
            # shuffle to add randomness
            rnd.shuffle(remaining)
            for c in remaining:
                d = self.demands[c]
                # try best insertion into existing route minimizing added distance
                best_r = None
                best_pos = None
                best_delta = None
                for r in routes:
                    if route_demand(r) + d > self.vehicle_capacity:
                        continue
                    # try append or insert positions
                    if len(r) == 0:
                        delta = self.distance_matrix[0, c] + self.distance_matrix[c, 0]
                        if best_delta is None or delta < best_delta:
                            best_r = r
                            best_pos = len(r)
                            best_delta = delta
                    else:
                        # try all insertion positions between nodes
                        prev_nodes = [0] + r
                        next_nodes = r + [0]
                        for idx in range(len(r)+1):
                            a = prev_nodes[idx]
                            b = next_nodes[idx]
                            delta = self.distance_matrix[a, c] + self.distance_matrix[c, b] - self.distance_matrix[a, b]
                            if best_delta is None or delta < best_delta:
                                best_r = r
                                best_pos = idx
                                best_delta = delta
                if best_r is not None:
                    best_r.insert(best_pos, c)
                else:
                    # create new route if possible
                    if d <= self.vehicle_capacity:
                        routes.append([c])
                    else:
                        # cannot satisfy capacity (shouldn't happen in valid CVRP), place alone
                        routes.append([c])
                assigned.add(c)
            # optionally merge small routes greedily to reduce count but obey capacity
            merged = True
            while merged:
                merged = False
                R = len(routes)
                if R <= 1:
                    break
                for i in range(len(routes)):
                    for j in range(i+1, len(routes)):
                        ri, rj = routes[i], routes[j]
                        if route_demand(ri) + route_demand(rj) <= self.vehicle_capacity:
                            # merge if reduces total distance
                            before = evaluate([ri]) + evaluate([rj])
                            merged_route = ri + rj
                            after = evaluate([merged_route])
                            if after <= before + 1e-9:
                                routes[i] = merged_route
                                routes.pop(j)
                                merged = True
                                break
                    if merged:
                        break
            return routes

        # Repair and normalize: ensure each customer appears once
        def repair_and_normalize(routes):
            # flatten to count
            counts = {}
            for r in routes:
                for c in r:
                    counts[c] = counts.get(c, 0) + 1
            # remove duplicates keeping first occurrence
            seen = set()
            new_routes = []
            for r in routes:
                nr = []
                for c in r:
                    if c not in seen:
                        nr.append(c)
                        seen.add(c)
                if len(nr) > 0:
                    new_routes.append(nr)
            # add missing customers
            missing = [c for c in range(1, self.n) if c not in seen]
            rnd.shuffle(missing)
            for c in missing:
                placed = False
                d = self.demands[c]
                # try to place into an existing route with capacity
                best_r = None
                best_delta = None
                for r in new_routes:
                    if route_demand(r) + d > self.vehicle_capacity:
                        continue
                    # append candidate
                    last = r[-1] if r else 0
                    delta = self.distance_matrix[last, c] + self.distance_matrix[c, 0] - self.distance_matrix[last, 0]
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = r
                if best_r is not None:
                    best_r.append(c)
                else:
                    new_routes.append([c])
            # ensure no route empty and capacities respected (split if too big)
            final_routes = []
            for r in new_routes:
                if route_demand(r) <= self.vehicle_capacity:
                    final_routes.append(r)
                else:
                    # split greedily
                    cur = []
                    cur_load = 0
                    for c in r:
                        if cur_load + self.demands[c] > self.vehicle_capacity:
                            final_routes.append(cur)
                            cur = [c]
                            cur_load = self.demands[c]
                        else:
                            cur.append(c)
                            cur_load += self.demands[c]
                    if cur:
                        final_routes.append(cur)
            return final_routes

        # Local memetic refine: optimized version replacing original
        def local_memetic_refine(routes, iterations):
            """
            Alternative local memetic refine using a best-improvement strategy across multiple
            neighborhood types: intra-route 2-opt, inter-route relocate, and inter-route swap.
            Operates on a shallow copy of the input routes, maintains per-route costs and loads,
            and applies the single best move per iteration (if it improves global cost).
            """
            dist = self.distance_matrix
            cap = self.vehicle_capacity
            demands = self.demands

            def route_cost(r):
                if not r:
                    return 0.0
                c = dist[0, r[0]]
                for i in range(len(r) - 1):
                    c += dist[r[i], r[i + 1]]
                c += dist[r[-1], 0]
                return c

            def route_load(r):
                return sum(demands[c] for c in r)

            # shallow copy routes
            best_routes = [list(r) for r in routes]
            route_costs = [route_cost(r) for r in best_routes]
            route_loads = [route_load(r) for r in best_routes]
            best_cost = sum(route_costs)

            it = 0
            EPS = 1e-9

            while it < iterations:
                n_routes = len(best_routes)
                best_delta = -EPS
                best_move = None  # dict describing move

                # 1) Intra-route 2-opt (reverse segment)
                for ri in range(n_routes):
                    r = best_routes[ri]
                    L = len(r)
                    if L <= 2:
                        continue
                    for i in range(0, L - 1):
                        a = 0 if i == 0 else r[i - 1]
                        for j in range(i + 1, L):
                            b = r[j]
                            d = 0 if j == L - 1 else r[j + 1]
                            c = r[i]
                            removed = dist[a, c] + dist[b, d]
                            added = dist[a, b] + dist[c, d]
                            delta = added - removed
                            if delta < best_delta:
                                best_delta = delta
                                best_move = {"type": "2opt", "ri": ri, "i": i, "j": j, "delta": delta}
                # 2) Inter-route relocate (single customer)
                for i in range(n_routes):
                    ri_list = best_routes[i]
                    Li = len(ri_list)
                    if Li == 0:
                        continue
                    for pos in range(Li):
                        c = ri_list[pos]
                        demand_c = demands[c]
                        prev_i = 0 if pos == 0 else ri_list[pos - 1]
                        next_i = 0 if pos == Li - 1 else ri_list[pos + 1]
                        removed_i = dist[prev_i, c] + dist[c, next_i]
                        added_i = dist[prev_i, next_i]
                        delta_removal = added_i - removed_i
                        for j in range(n_routes):
                            if i == j:
                                continue
                            if route_loads[j] + demand_c > cap:
                                continue
                            rj_list = best_routes[j]
                            Lj = len(rj_list)
                            if Lj == 0:
                                delta_ins = dist[0, c] + dist[c, 0]
                                total_delta = delta_removal + delta_ins
                                if total_delta < best_delta:
                                    best_delta = total_delta
                                    best_move = {"type": "relocate", "from": i, "to": j, "from_pos": pos,
                                                 "to_pos": 0, "delta": total_delta, "empty_target": True}
                            else:
                                for ins in range(Lj + 1):
                                    prev_j = 0 if ins == 0 else rj_list[ins - 1]
                                    next_j = 0 if ins == Lj else rj_list[ins]
                                    added_j = dist[prev_j, c] + dist[c, next_j]
                                    removed_j = dist[prev_j, next_j]
                                    delta_ins = added_j - removed_j
                                    total_delta = delta_removal + delta_ins
                                    if total_delta < best_delta:
                                        best_delta = total_delta
                                        best_move = {"type": "relocate", "from": i, "to": j, "from_pos": pos,
                                                     "to_pos": ins, "delta": total_delta, "empty_target": False}
                # 3) Inter-route swap (swap one customer from route A with one from route B)
                for i in range(n_routes):
                    ri_list = best_routes[i]
                    Li = len(ri_list)
                    if Li == 0:
                        continue
                    for j in range(i + 1, n_routes):
                        rj_list = best_routes[j]
                        Lj = len(rj_list)
                        if Lj == 0:
                            continue
                        # iterate all pairs of positions
                        for pi in range(Li):
                            ci = ri_list[pi]
                            demand_ci = demands[ci]
                            prev_ai = 0 if pi == 0 else ri_list[pi - 1]
                            next_ai = 0 if pi == Li - 1 else ri_list[pi + 1]
                            for pj in range(Lj):
                                cj = rj_list[pj]
                                demand_cj = demands[cj]
                                # capacity feasibility after swap
                                load_i_after = route_loads[i] - demand_ci + demand_cj
                                load_j_after = route_loads[j] - demand_cj + demand_ci
                                if load_i_after > cap or load_j_after > cap:
                                    continue
                                prev_bj = 0 if pj == 0 else rj_list[pj - 1]
                                next_bj = 0 if pj == Lj - 1 else rj_list[pj + 1]
                                # removed edges
                                removed = (dist[prev_ai, ci] + dist[ci, next_ai] +
                                           dist[prev_bj, cj] + dist[cj, next_bj])
                                # added edges after swapping ci<->cj
                                added = (dist[prev_ai, cj] + dist[cj, next_ai] +
                                         dist[prev_bj, ci] + dist[ci, next_bj])
                                # special case when prev_ai == cj or next_ai == cj etc would be handled correctly because nodes are unique across routes
                                delta = added - removed
                                if delta < best_delta:
                                    best_delta = delta
                                    best_move = {"type": "swap", "i": i, "j": j, "pi": pi, "pj": pj, "delta": delta}

                # If no improving move found, stop
                if best_move is None:
                    break

                # Apply the best move found
                mv = best_move
                if mv["type"] == "2opt":
                    ri = mv["ri"]
                    i = mv["i"]
                    j = mv["j"]
                    # apply reversal
                    r = best_routes[ri]
                    r[i:j + 1] = reversed(r[i:j + 1])
                    route_costs[ri] += mv["delta"]
                    best_cost += mv["delta"]
                elif mv["type"] == "relocate":
                    frm = mv["from"]
                    to = mv["to"]
                    from_pos = mv["from_pos"]
                    to_pos = mv["to_pos"]
                    # Ensure indices consistent if we remove route before inserting new route
                    # Always remove from the higher index first to avoid shifting if needed.
                    # But since we are moving element between lists rather than creating new lists, handle carefully.
                    c = best_routes[frm][from_pos]
                    demand_c = demands[c]
                    # compute removal delta for bookkeeping (we already have mv["delta"] total)
                    # Remove element
                    best_routes[frm].pop(from_pos)
                    route_loads[frm] -= demand_c
                    # update route cost for frm: recalc by applying delta_removal
                    # We don't have delta_removal stored here; simplest correct approach is to recompute route cost for affected routes
                    route_costs[frm] = route_cost(best_routes[frm])
                    # If frm became empty, remove that route entry
                    removed_route_index = None
                    if len(best_routes[frm]) == 0:
                        # remove the empty route
                        best_routes.pop(frm)
                        route_costs.pop(frm)
                        route_loads.pop(frm)
                        removed_route_index = frm
                        # adjust 'to' index if necessary
                        if to > frm:
                            to -= 1
                    # Insert into target route (if target was empty and originally an empty route location, treat appropriately)
                    if mv.get("empty_target", False):
                        # insert as a new single-node route at position 'to' (we will create new entry)
                        best_routes.insert(to, [c])
                        route_loads.insert(to, demand_c)
                        route_costs.insert(to, route_cost([c]))
                    else:
                        best_routes[to].insert(to_pos, c)
                        route_loads[to] += demand_c
                        route_costs[to] = route_cost(best_routes[to])
                    best_cost += mv["delta"]
                elif mv["type"] == "swap":
                    i = mv["i"]
                    j = mv["j"]
                    pi = mv["pi"]
                    pj = mv["pj"]
                    ci = best_routes[i][pi]
                    cj = best_routes[j][pj]
                    # swap elements
                    best_routes[i][pi], best_routes[j][pj] = cj, ci
                    # update loads (swapping doesn't change loads, but keep consistent)
                    route_loads[i] = route_loads[i] - demands[ci] + demands[cj]
                    route_loads[j] = route_loads[j] - demands[cj] + demands[ci]
                    # recompute route costs for affected routes (safe and simple)
                    route_costs[i] = route_cost(best_routes[i])
                    route_costs[j] = route_cost(best_routes[j])
                    best_cost += mv["delta"]
                else:
                    # unknown move type (should not happen)
                    break

                it += 1

            # remove empty routes and return
            final = [r for r in best_routes if len(r) > 0]
            return final

        # Population replace
        def population_replace(pop, candidate, strategy="replace_worst"):
            cand_cost = evaluate(candidate)
            if strategy == "replace_worst":
                costs = [evaluate(p) for p in pop]
                worst_idx = int(np.argmax(costs))
                if cand_cost + 1e-9 < costs[worst_idx]:
                    pop[worst_idx] = candidate
            elif strategy == "random":
                idx = rnd.randrange(len(pop))
                pop[idx] = candidate
            elif strategy == "always_insert":
                # keep elitism by removing worst and inserting candidate
                costs = [evaluate(p) for p in pop]
                worst_idx = int(np.argmax(costs))
                pop[worst_idx] = candidate
            return pop

        # Identify hotspots: routes with highest cost per demand
        def identify_hotspots(pop, criteria):
            hotspots = []
            top_k = criteria.get("top_k", 3)
            scored = []
            for p in pop:
                for r in p:
                    d = route_demand(r)
                    c = 0.0
                    if len(r) > 0:
                        prev = 0
                        for cust in r:
                            c += self.distance_matrix[prev, cust]
                            prev = cust
                        c += self.distance_matrix[prev, 0]
                    score = c / max(1, d)
                    scored.append((score, r))
            scored.sort(reverse=True, key=lambda x: x[0])
            for i in range(min(top_k, len(scored))):
                hotspots.append(scored[i][1])
            return hotspots

        # Intensify on fragment: perform local search and add new fragments to pool
        def intensify_on_fragment(fragment, pool, compat, budget):
            # try to create variations by shuffling internal order and attempting to insert into pop best
            for _ in range(budget):
                frag = fragment[:]
                if len(frag) > 1:
                    a = rnd.randrange(len(frag))
                    b = rnd.randrange(len(frag))
                    frag[a], frag[b] = frag[b], frag[a]
                pool.add(frag, score=1.0)
                compat.online_update([frag], score=10.0)

        # Diversify pool and sizes
        def diversify_pool_and_sizes(pool, sizes):
            # add random fragments and mutate sizes
            all_customers = list(range(1, self.n))
            pool.diversify(all_customers, sizes, rnd)
            # tweak sizes a bit
            for i in range(len(sizes)):
                if rnd.random() < 0.3:
                    sizes[i] = max(1, sizes[i] + rnd.choice([-1, 1]))
            return pool, sizes

        # Stagnation detection
        def stagnation_detected(history, limit):
            return history >= limit

        # Decode function: from routes to flattened list with zeros separating routes
        def decode(individual_routes):
            flat = []
            for r in individual_routes:
                flat.append(0)
                flat.extend(r)
            flat.append(0)
            # compress possible duplicate zeros
            out = []
            for x in flat:
                if len(out) == 0:
                    out.append(x)
                else:
                    if not (out[-1] == 0 and x == 0):
                        out.append(x)
            if out[0] != 0:
                out.insert(0, 0)
            if out[-1] != 0:
                out.append(0)
            return out

        # --- Main algorithm initialization ---
        all_customers = list(range(1, self.n))
        POP = initialize_population(pop_size)
        POOL = FragmentPool()
        COMPAT_MODEL = CompatModel(self.n)

        # build initial fragments from population
        for p in POP:
            for r in p:
                L = len(r)
                for s in frag_sizes:
                    if s <= 0:
                        continue
                    if L >= s:
                        for i in range(0, L - s + 1):
                            seq = r[i:i+s]
                            POOL.add(seq, score=1.0)

        # best
        costs = [evaluate(p) for p in POP]
        best_idx = int(np.argmin(costs))
        best = deepcopy(POP[best_idx])
        best_cost = costs[best_idx]

        start_time = time.time()
        last_improve_time = start_time
        no_improve_iters = 0
        iter_count = 0

        # main loop
        while time.time() - start_time < time_limit:
            iter_count += 1
            # select parents
            parents = []
            if parent_strategy == "tournament":
                # tournament selection of 2 parents
                for _ in range(2):
                    a, b = rnd.randrange(len(POP)), rnd.randrange(len(POP))
                    if evaluate(POP[a]) < evaluate(POP[b]):
                        parents.append(deepcopy(POP[a]))
                    else:
                        parents.append(deepcopy(POP[b]))
            else:
                parents = [deepcopy(rnd.choice(POP)) for _ in range(2)]

            # sample fragments
            fragments = sample_fragments_from_parents(parents, POOL, COMPAT_MODEL.co, sample_budget)
            # reconstruct
            candidate = constraint_aware_reconstruct(fragments, all_customers, assembler)
            # repair/normalize
            candidate = repair_and_normalize(candidate)
            # local memetic refine
            candidate = local_memetic_refine(candidate, local_ops.get("2opt_iters", 50))
            # evaluate and update pool & compat model
            score = evaluate(candidate)
            POOL.update_with_candidate(fragments, score)
            COMPAT_MODEL.online_update(fragments, score)
            # population replacement
            POP = population_replace(POP, candidate, replacement_strategy)
            # hotspots and intensify
            hotspots = identify_hotspots(POP, hotspot_criteria)
            for h in hotspots:
                Intensify_iters = min(intensify_budget, max(1, len(h)))
                intensify_on_fragment(h, POOL, COMPAT_MODEL, Intensify_iters)
            # stagnation handling
            if score + 1e-9 < best_cost:
                best = deepcopy(candidate)
                best_cost = score
                last_improve_time = time.time()
                no_improve_iters = 0
            else:
                no_improve_iters += 1
            if no_improve_iters > stagnation_limit:
                POOL, frag_sizes = diversify_pool_and_sizes(POOL, frag_sizes)
                no_improve_iters = 0
            # POOL aging
            POOL.decay()
            # time break check
            if time.time() - start_time >= time_limit:
                break

        return decode(best)
